fun Binary_Search(@init<table> collection, target, size):
    low = 0
    high = size - 1

    while (low <= high):
        // Calculate middle index safely using floor division
        mid = floor((low + high) / 2)

        // Get value at the middle index
        @mark<mid, highlight, yellow> val = collection[mid]

        // Check if target is present at mid
        if (val == target):
            @mark<mid, highlight, green> return mid
        end if

        // If target is greater, ignore left half
        if (val < target):
            @mark<low, outline, yellow> low = mid + 1
        end if

        // If target is smaller, ignore right half
        if (val > target):
            @mark<high, outline, yellow> high = mid - 1
        end if
    end while

    @log<warn, "Target not found"> return -1
end fun

