fun Binary_Search_Recursive(@init<table> collection, target, low, high):
    // Base case: if low exceeds high, target is not present
    if (low > high):
        @log<warn, "Not found"> return -1
    end if

    // Calculate middle index using floor division
    mid = floor((low + high) / 2)

    // Get value at the middle
    @mark<mid, highlight, yellow> val = collection[mid]

    // Check if target is present at mid
    if (val == target):
        @mark<mid, highlight, green> return mid
    end if

    // If target is smaller than mid, then it can only be in left subarray
    if (val > target):
        next_high = mid - 1
        @mark<next_high, outline, yellow> return Binary_Search_Recursive(collection, target, low, next_high)
    end if

    // Otherwise the target can only be in right subarray
    next_low = mid + 1
    @mark<next_low, outline, yellow> return Binary_Search_Recursive(collection, target, next_low, high)
end fun

fun Binary_Search_Driver(collection, target):
    n = length(collection)
    initial_low = 0
    initial_high = n - 1
    return Binary_Search_Recursive(collection, target, initial_low, initial_high)
end fun

