data = arr[5, 1, 4, 2, 8, 0, 2]

fun Cocktail_Shaker_Sort(@init<table> array):
    n = length(array)
    left = 0
    right = n - 1
    swapped = True

    // Continue sorting while elements were swapped in the previous pass
    while (swapped == True):
        swapped = False

        // Forward pass: bubble the largest element to the right
        for (i = left, i < right, i += 1):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap(array[i], array[i + 1])
                swapped = True
            end if
        end for

        // If no elements were swapped, the array is sorted
        if (swapped == False):
            break
        end if

        swapped = False
        right -= 1

        // Backward pass: bubble the smallest element to the left
        for (i = right, i > left, i -= 1):
            @mark<i, outline, yellow> if (array[i] < array[i - 1]):
                @mark<i, highlight, green> swap(array[i], array[i - 1])
                swapped = True
            end if
        end for

        left += 1
    end while

    return array
end fun

