fun Separate_Even_Odd(@init<table> array):
    n = length(array)

    // Initialize left pointer at the start
    left = 0

    // Initialize right pointer at the end
    right = n - 1

    while (left < right):
        // Move left pointer forward while the element is even
        while (left < right):
            rem = array[left] % 2
            @mark<left, outline, yellow> if (rem != 0):
                break
            end if
            left += 1
        end while

        // Move right pointer backward while the element is odd
        while (left < right):
            rem = array[right] % 2
            @mark<right, outline, yellow> if (rem == 0):
                break
            end if
            right -= 1
        end while

        // Swap the misplaced even and odd elements
        if (left < right):
            @mark<left, highlight, green> swap(array[left], array[right])
            left += 1
            right -= 1
        end if
    end while

