// Helper function to maintain max heap property for a subtree rooted at index i
fun Heapify(@init<table> array, n, i):
    largest = i
    left = 2 * i + 1
    right = 2 * i + 2

    // Check if left child exists and is greater than root
    l_valid = 0
    @mark<left, outline, yellow> if (left < n):
        @mark<left, text, fg> if (array[left] > array[largest]):
            largest = left
        end if
    end if

    // Check if right child exists and is greater than current largest
    @mark<right, outline, yellow> if (right < n):
        @mark<right, text, fg> if (array[right] > array[largest]):
            largest = right
        end if
    end if

    // If largest is not root, swap and continue heapifying the affected subtree
    @mark<i, outline, yellow> if (largest != i):
        @mark<largest, highlight, green> swap(array[i], array[largest])
        Heapify(array, n, largest)
    end if

    return array
end fun

// Main function to perform heap sort
fun Heap_Sort(@init<table> array):
    n = length(array)

    // Build max heap by rearranging array
    i = floor(n / 2) - 1
    while (i >= 0):
        Heapify(array, n, i)
        i -= 1
    end while

    // Extract elements from heap one by one
    i = n - 1
    while (i > 0):
        @mark<i, highlight, green> swap(array[0], array[i])
        Heapify(array, i, 0)
        i -= 1
    end while

    return array
end fun

