fun Check_Palindrome(@init<table> array):
    // Initialize left and right pointers at the bounds of the array
    n = length(array)
    low = 0
    high = n - 1

    while (low < high):
        // Mark current comparing elements with outlines
        @mark<low, outline, yellow>
        @mark<high, outline, yellow> if (array[low] != array[high]):
            // Mismatch found, return false
            @mark<low, highlight, red> return 0
        end if

        // Move pointers inward
        low += 1
        high -= 1
    end while

    // Array reads the same forwards and backwards
    return 1
