// Boyer-Moore Majority Vote Algorithm

data = arr[3, 3, 4, 3, 2, 3, 3]

fun Find_Majority(@init<table> nums):
    n = length(nums)
    candidate = -1
    count = 0

    // Phase 1: Find a potential majority candidate
    for (i = 0; i < n; i += 1):
        @mark<i, outline, yellow> if (count == 0):
            candidate = nums[i]
            count = 1
        else:
            @mark<i, text, fg> if (nums[i] == candidate):
                count += 1
            else:
                count -= 1
            end if
        end if
    end for

    // Phase 2: Verify if the candidate actually appears more than n / 2 times
    verify_count = 0
    for (j = 0; j < n; j += 1):
        @mark<j, outline, yellow> if (nums[j] == candidate):
            @mark<j, highlight, green> verify_count += 1
        end if
    end for

    threshold = floor(n / 2)
    if (verify_count > threshold):
        @log<info, "Majority found"> return candidate
    end if

    @log<warn, "No majority element"> return -1
end fun

result = Find_Majority(data)

