// Lomuto partition scheme for rearranging sub-arrays around a pivot
fun Lomuto_Partition(@init<table> array, low, high):
    @mark<high, highlight, yellow> pivot = array[high]

    i = low - 1

    for (j = low, j < high, j += 1):
        @mark<j, outline, yellow> if (array[j] < pivot):
            i += 1
            @mark<i, highlight, green> swap(array[i], array[j])
        end if
    end for

    @mark<i, highlight, green> swap(array[i + 1], array[high])

    return i + 1
end fun

// Recursive Quickselect function to find the k-th smallest element (k counts from 1)
fun Quickselect(array, low, high, k_index):
    if (low <= high):
        pi = Lomuto_Partition(array, low, high)

        if (pi == k_index):
            @mark<pi, highlight, green> return array[pi]
        end if

        if (pi > k_index):
            return Quickselect(array, low, pi - 1, k_index)
        end if

        return Quickselect(array, pi + 1, high, k_index)
    end if

    return -1
end fun

// Wrapper function to adjust 1-based k to 0-based index
fun Find_Kth_Smallest(array, k):
    n = length(array)
    target_index = k - 1
    return Quickselect(array, 0, n - 1, target_index)
end fun

