fun Remove_Duplicates(@init<table> array):
    n = length(array)

    // Handle edge case of an empty array
    if (n == 0):
        return 0
    end if

    // i points to the last unique element found
    i = 0

    // j scans through the rest of the array
    for (j = 1; j < n; j += 1):
        @mark<j, outline, yellow> if (array[j] != array[i]):
            @mark<i, text, fg> i += 1
            @mark<i, highlight, green> array[i] = array[j]
        end if
    end for

    // Return the count of unique elements
    return i + 1
end fun

