fun Reverse_Array(@init<table> array):
    // initialize left pointer at the beginning
    left = 0

    // initialize right pointer at the end
    n = length(array)
    right = n - 1

    // move pointers inward until they meet or cross
    while (left < right):
        @mark<left, outline, yellow> @mark<right, outline, yellow> if (left < right):
            // swap elements at left and right pointers
            @mark<left, highlight, green> @mark<right, highlight, green> swap(array[left], array[right])
        end if

        // advance left pointer
        left += 1

        // retreat right pointer
        right -= 1
    end while

    @log<info, "Array reversal complete"> return array
end fun

