fun Shell_Sort(@init<table> array):
    n = length(array)

    // Start with a large gap, then reduce the gap
    gap = floor(n / 2)
    while (gap > 0):

        // Perform a gapped insertion sort for this gap size
        for (i = gap, i < n, i += 1):
            temp = array[i]
            j = i

            // Shift earlier gap-sorted elements up until the correct location for array[i] is found
            @mark<j, outline, yellow> while (j >= gap and array[j - gap] > temp):
                prevIdx = j - gap
                @mark<prevIdx, outline, yellow> if (array[prevIdx] > temp):
                    @mark<j, text, fg> array[j] = array[prevIdx]
                end if
                j = j - gap
            end while

            array[j] = temp
        end for

        gap = floor(gap / 2)
    end while

    return array
end fun

