fun Two_Sum(@init<table> array, target):
    // Initialize left pointer at the beginning and right pointer at the end
    left = 0
    n = length(array)
    right = n - 1

    while (left < right):
        @mark<left, outline, yellow>
        @mark<right, outline, yellow>

        current_sum = array[left] + array[right]

        // Check if current pair matches the target sum
        @mark<left, text, fg> if (current_sum == target):
            @mark<left, highlight, green>
            @mark<right, highlight, green>
            @log<info, "Pair found">
            res = arr[left, right]
            return res
        end if

        // Adjust pointers based on comparison with target
        if (current_sum < target):
            left += 1
        else:
            right -= 1
        end if
    end while

    // Return [-1, -1] if no such pair exists
    not_found = arr[-1, -1]
    return not_found
end fun

